package guru.interlis.cli;

import java.nio.file.Path;
import java.util.*;

/** Host path and output-mode validation before any artifact is written. */
public final class OutputPlanner {
    /** Paths are resolved against the injected directory, including file URI inputs. */
    public OutputPlan plan(ParsedCommand command, CliEnvironment environment) {
        Objects.requireNonNull(command, "command");
        Objects.requireNonNull(environment, "environment");
        var sources = command.files().stream().map(value -> local(value, environment)).toList();
        var targets = new ArrayList<Path>();
        boolean stdout = true;
        if (command.command().equals("format")) {
            if (command.has("--check") && command.has("--write"))
                throw new CliUsageException("--check and --write are mutually exclusive");
            if (new HashSet<>(sources).size() != sources.size())
                throw new CliUsageException("duplicate formatting source");
            var realPaths = new HashSet<Path>();
            var fileKeys = new HashSet<Object>();
            var withoutKeys = new ArrayList<Path>();
            for (Path source : sources) {
                try {
                    Path real = source.toRealPath();
                    Object key = java.nio.file.Files.readAttributes(real,
                            java.nio.file.attribute.BasicFileAttributes.class).fileKey();
                    if (!realPaths.add(real) || (key != null && !fileKeys.add(key))
                            || withoutKeys.stream().anyMatch(previous -> sameFile(previous, source)))
                        throw new CliUsageException("duplicate formatting source");
                    if (key == null) withoutKeys.add(real);
                } catch (java.io.IOException failure) { throw loadFailure(failure); }
            }
            if (command.has("--write")) targets.addAll(sources);
            stdout = !command.has("--write") && !command.has("--check");
        }
        command.value("--write-lock").ifPresent(value -> {
            Path target = local(value, environment);
            if (sources.stream().anyMatch(source -> sameFile(source, target)))
                throw new CliUsageException("lock output collides with a source");
            targets.add(target);
        });
        return new OutputPlan(targets, stdout);
    }

    private static Path local(String value, CliEnvironment environment) {
        try {
            Path path = value.startsWith("file:") ? Path.of(java.net.URI.create(value)) : Path.of(value);
            return environment.workingDirectory().resolve(path).toAbsolutePath().normalize();
        } catch (IllegalArgumentException invalid) { throw new CliUsageException("invalid local output path"); }
    }

    static boolean sameFile(Path first, Path second) {
        if (first.equals(second)) return true;
        try {
            return java.nio.file.Files.exists(first) && java.nio.file.Files.exists(second)
                    && java.nio.file.Files.isSameFile(first, second);
        } catch (java.io.IOException failure) { throw loadFailure(failure); }
    }

    private static guru.interlis.repository.SourceLoadException loadFailure(java.io.IOException failure) {
        var reason = failure instanceof java.nio.file.NoSuchFileException
                ? guru.interlis.repository.SourceLoadException.Reason.NOT_FOUND
                : failure instanceof java.nio.file.AccessDeniedException
                ? guru.interlis.repository.SourceLoadException.Reason.ACCESS_DENIED
                : guru.interlis.repository.SourceLoadException.Reason.IO_FAILURE;
        return new guru.interlis.repository.SourceLoadException(reason, "source identity could not be inspected", failure);
    }
}

package guru.interlis.cli;

import java.util.*;

/** Deeply immutable option occurrences and file arguments, each in input order. */
public record ParsedCommand(String command, Map<String, List<List<String>>> options,
                            List<String> files) implements CliParseOutcome {
    public ParsedCommand {
        Objects.requireNonNull(command, "command");
        var copy = new LinkedHashMap<String, List<List<String>>>();
        Objects.requireNonNull(options, "options").forEach((name, occurrences) ->
                copy.put(Objects.requireNonNull(name), occurrences.stream().map(List::copyOf).toList()));
        options = Collections.unmodifiableMap(copy);
        files = List.copyOf(Objects.requireNonNull(files, "files"));
    }

    public boolean has(String option) { return options.containsKey(option); }
    public List<List<String>> occurrences(String option) { return options.getOrDefault(option, List.of()); }
    public Optional<String> value(String option) {
        var values = occurrences(option);
        return values.isEmpty() || values.getFirst().isEmpty() ? Optional.empty()
                : Optional.of(values.getFirst().getFirst());
    }
    public List<String> values(String option) {
        return occurrences(option).stream().filter(values -> !values.isEmpty()).map(List::getFirst).toList();
    }
}
package guru.interlis.cli;

import java.util.*;

/** Immutable command grammar. Option order is also the deterministic help order. */
public record CommandSpec(String command, List<Option> options, boolean acceptsFiles) {
    /** Copies the ordered definitions and rejects duplicate option names. */
    public CommandSpec {
        Objects.requireNonNull(command, "command");
        options = List.copyOf(Objects.requireNonNull(options, "options"));
        if (command.isBlank() || options.stream().map(Option::name).distinct().count() != options.size()) {
            throw new IllegalArgumentException("invalid command or duplicate option");
        }
    }

    /** A flag has zero values. Repeated occurrences retain input order. */
    public record Option(String name, int valueCount, boolean repeatable) {
        public Option {
            Objects.requireNonNull(name, "name");
            if (!name.startsWith("-") || name.equals("--") || valueCount < 0) {
                throw new IllegalArgumentException("invalid option definition");
            }
        }
    }

    /** Returns the explicit new CLI grammar; unknown commands are API errors. */
    public static CommandSpec standard(String command) {
        var options = new ArrayList<Option>();
        boolean files = switch (command) {
            case "help", "capabilities" -> false;
            case "version" -> { options.add(new Option("--json", 0, false)); yield false; }
            case "format" -> {
                for (String flag : List.of("--check", "--write")) options.add(new Option(flag, 0, false));
                for (String value : List.of("--indent", "--line-ending")) options.add(new Option(value, 1, false));
                yield true;
            }
            case "check", "compile", "analyze", "diagram" -> {
                options.add(new Option("--json", 0, false));
                options.add(new Option("--root", 1, true));
                if (command.equals("diagram")) options.add(new Option("--format", 1, false));
                options.add(new Option("--repository", 1, true));
                options.add(new Option("--model-pin", 4, true));
                options.add(new Option("--source-pin", 2, true));
                for (String name : List.of("--read-lock", "--write-lock", "--cache", "--config", "--warnings", "--connect-timeout", "--read-timeout", "--request-timeout", "--proxy", "--proxyPort"))
                    options.add(new Option(name, 1, false));
                options.add(new Option("--offline", 0, false));
                options.add(new Option("--no-cache", 0, false));
                options.add(new Option("--no-proxy", 0, false));
                options.add(new Option("--explain-config", 0, false));
                yield true;
            }
            default -> throw new IllegalArgumentException("unknown command: " + command);
        };
        if (files) {
            options.add(new Option("--verbose", 0, false));
            options.add(new Option("--diagnostic-language", 1, false));
            options.add(new Option("--color", 1, false));
        }
        return new CommandSpec(command, options, files);
    }
}

